                setattr(self, fname, args[i])
            elif fname in kwargs:
                setattr(self, fname, kwargs[fname])
            else:
                setattr(self, fname, None)

    def srid(self):
        return self._srid_map.get(id(self), None)

    attrs = {
        'name': name,
        '__init__': __init__,
        '__repr__': lambda self: f"{name}({', '.join(str(getattr(self, f)) for f in self._fields)})",
        'srid': property(srid),
    }

    # Create the class dynamically
    new_class = type(name, (object,), attrs)

