    return [seq[i] for i in permutation]

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    if not seq:
        return []
    items = list(seq)
    h = sum(hash(item) for item in items)
    for i in range(len(items) - 1, 0, -1):
        j = (h * (i + 1) + i * (i - 1)) % (i + 1)
        items[i], items[j] = items[j], items[i]
    return items

