    def decorator(func):
        cache = {}
        freq = {}
        key_order = []

        def wrapper(*args, **kwargs):
            if typed:
                key = (args, tuple(sorted(kwargs.items())))
            else:
                key = (args, tuple(sorted(kwargs.items())))

            if key in cache:
                freq[key] += 1
                return cache[key]

            result = func(*args, **kwargs)
            cache[key] = result
            freq[key] = 1
            key_order.append(key)

            if len(key_order) > maxsize:
                min_freq = min(freq.values())
                while key_order and freq[key_order[0]] == min_freq:
                    evict_key = key_order.pop(0)
                    del freq[evict_key]
                    if evict_key in cache:
                        del cache[evict_key]
                    if len(key_order) <= maxsize:
                        break

            return result

        wrapper.cache = cache
        wrapper.forget = lambda *args, **kwargs: (
            cache.pop((args, tuple(sorted(kwargs.items()))), None)
            if (args, tuple(sorted(kwargs.items()))) in cache
            else None
        )
        wrapper.clear = lambda: (cache.clear(), freq.clear(), key_order.clear())

        return wrapper
    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """
    def decorator(func):
        cache = LFUCache(maxsize)

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, kwargs)
            if key in cache:
                cache.touch(key)
            else:
                cache[key] = func(*args, **kwargs)
            return cache[key]

        wrapper.cache = cache
        return wrapper

    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """

    def decorator(func):
        if maxsize is None:
            return func

        if maxsize <= 0:
            raise ValueError('maxsize must be positive')

        cache = {}
        usage = defaultdict(int)
        minfreq = 0

        def _key(func, args, kwargs, typed=True):
            key = {
                '__args__': args,
                '__kwargs__': kwargs
            }
            if typed:
                key['__type__'] = type(args[0]) if args else None
            return key

        @wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal minfreq
            key = _key(func, args, kwargs, typed)
            if key in cache:
                usage[key] += 1
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            usage[key] = 1
            minfreq = 1
            if len(cache) > maxsize:
                for k, freq in list(usage.items()):
                    if freq == minfreq:
                        del cache[k]
                        del usage[k]
                        break
                minfreq = min(usage.values())
            return result

        return wrapper

    return decorator

