import functools

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """

    def decorator(method):
        if lock is None:
            @functools.wraps(method)
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                try:
                    k = key(*args, **kwargs)
                except Exception:
                    # If the key function fails, just call the method
                    return method(self, *args, **kwargs)
                try:
                    return c[k]
                except KeyError:
                    # key was not found in cache
                    pass
                v = method(self, *args, **kwargs)
                try:
                    c[k] = v
                except ValueError:
                    # value is not hashable or otherwise not storable?
                    # (hashkey typically returns a tuple, which is hashable,
                    #  but some custom keys might fail)
                    pass
                except Exception:
                    pass
                return v
        else:
            @functools.wraps(method)
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                try:
                    k = key(*args, **kwargs)
                except Exception:
                    # If the key function fails, just call the method
                    return method(self, *args, **kwargs)
                try:
                    with lock(self):
                        return c[k]
                except KeyError:
                    # key was not found in cache
                    pass
                v = method(self, *args, **kwargs)
                try:
                    with lock(self):
                        c[k] = v
                except ValueError:
                    pass
                except Exception:
                    pass
                return v
        return wrapper
    return decorator
