def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    class_name = self.__class__.__name__.split('.')[-1]
    if class_name.startswith('Py'):
        implementation_name = class_name[2:]
    elif class_name.startswith('Fallback'):
        implementation_name = class_name[8:]
    else:
        implementation_name = class_name
    module_name = self.__class__.__module__
    return getattr(__import__(module_name, fromlist=[implementation_name]), implementation_name)
