def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []

    # Remove None entries
    classes = [cls for cls in classes if cls is not None]

    if not classes:
        return []

    # Remove duplicates while preserving order
    seen = set()
    unique_classes = []
    for cls in classes:
        if cls not in seen:
            seen.add(cls)
            unique_classes.append(cls)

    # Now remove any class that is a base class of another class in the list
    # A class is redundant if it is a base class of another class in the list
    # (i.e., if cls is in other.__mro__)
    minimal = []
    for cls in unique_classes:
        redundant = False
        for other in unique_classes:
            if cls is other:
                continue
            if issubclass(cls, other):
                if cls is not other:
                    redundant = True
                    break
        if not redundant:
            minimal.append(cls)

    return minimal
