def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []
    minimized = [classes[-1]]
    for cls in classes[-2::-1]:
        if not any(issubclass(cls, m) for m in minimized):
            minimized.append(cls)
    reversed_minimized = minimized[::-1]
    key = lambda x: (str(x.__module__) + x.__name__ if x is not object else '#object')
    return sorted(reversed_minimized, key=key)

