def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    try:
        # Reset current context to empty dict
        self.current = {}

        # Reinitialize bins
        if hasattr(self, 'initial_value') and self.initial_value is not None:
            # If initial_value is set, reinitialize bins to the initial value
            for bin_name in self.bins:
                if isinstance(self.bins[bin_name], list):
                    # Nested histogram case: reinitialize all leaf bins
                    for key in self.bins[bin_name]:
                        self.bins[bin_name][key] = self.initial_value
                        # Reset context for nested histogram
                        self.current[key] = {}
                else:
                    self.bins[bin_name] = self.initial_value
                    self.current[bin_name] = {}
        else:
            # Otherwise, reinitialize bins using make_bins
            self.bins = self.make_bins()
            # Reset context for all top-level and nested bins
            for bin_name, bin_obj in self.bins.items():
                if isinstance(bin_obj, dict):
                    # Nested histogram
                    self.current[bin_name] = {}
                else:
                    self.current[bin_name] = {}

        # Reset total count if it exists
        if hasattr(self, 'total_count'):
            self.total_count = 0

    except Exception as e:
