    def _update_context(self, context):
        """Update *context* with the properties of this graph.

        *context.error* is appended with indices of errors.
        Example subcontext for a graph with fields "E,t,error_E_low":
        {"error": {"x_low": {"index": 2}}}.
        Note that error names are called "x", "y" and "z"
        (this corresponds to first three coordinates,
        if they are present), which allows to simplify plotting.
        Existing values are not removed
        from *context.value* and its subcontexts.

        Called on "destruction" of the graph (for example,
        in :class:`.ToCSV`). By destruction we mean conversion
        to another structure (like text) in the flow.
        The graph object is not really destroyed in this process.
        """
        # We assume 'self' has the error data and context structure is as described
        error = getattr(self, 'error', None)
        if error:
            if 'error' not in context:
                context['error'] = {}
            for axis, error_data in error.items():
                # Map axis names 'x', 'y', 'z' etc. to appropriate context keys
                # The description says error names are called "x", "y" and "z"
                if isinstance(error_data, dict):
                    if axis not in context['error']:
                        context['error'][axis] = {}
                    context['error'][axis].update(error_data)
                else:
                    # If error_data is not a dict, store it as is
                    context['error'][axis] = error_data

        # Update context.value if it exists in self
        value = getattr(self, 'value', None)
        if value:
            if 'value' not in context:
                context['value'] = {}
            if isinstance(value, dict):
                for key, val in value.items():
                    if isinstance(val, dict):
                        if key not in context['value']:
                            context['value'][key] = {}
                        context['value'][key].update(val)
                    else:
                        context['value'][key] = val

