            val1 = d1[key]
            val2 = d2[key]

            if _is_dict(val1) and _is_dict(val2):
                # Both values are dictionaries, recurse
                if level == -1:  # Infinite recursion
                    next_level = -1
                else:
                    next_level = level - 1
                sub_diff = difference(val1, val2, level=next_level)
                if sub_diff:  # Only include if there's a difference
                    result[key] = sub_diff
            else:
                # At least one value is not a dict
                if val1 != val2:
                    # If the values are different, include the item from d1
                    result[key] = val1
                # If values are the same, don't include it

    return result
