def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if level == 0:
        return {}

    new_level = -1
    if level > 0:
        new_level = level - 1

    if d1 == d2:
        return {}

    diff = {k: v for k, v in d1.items() if k not in d2 or d2[k] != v}

    # To apply maximum depth of recursion, remove every element from diff which are a dict
    # and present in both d1 and d2 as well (to be processed separately in recursion step)
    diff = {k: v for k, v in diff.items() if k not in d2 or not isinstance(v, dict)}

    # For keys which are a dict present in both d1 and d2 as well, recursively find their difference
    for key, value in d1.items():
        if key in d2 and _dicts_equal(value, d2[key]) is False:  # not in d2[key] but in diff (added above)
            sub_diff = difference(value, d2[key], new_level)
            if sub_diff:
                diff[key] = sub_diff
    return diff

