def _validate_labels(labels):
    errors = []

    if not isinstance(labels, dict):
        errors.append({
            'label': str(labels),
            'message': 'labels must be a dict'
        })
        raise ValidationError(errors)

    # regex for valid keys
    key_regex = re.compile(r'^[a-zA-Z_][a-zA-Z0-9_]*$')
    # regex for values
    value_regex = re.compile(r'^[a-zA-Z_][a-zA-Z0-9_]*$')

    for key, value in labels.items():
        # key validation
        if not isinstance(key, str):
            errors.append({
                str(key): 'expected string or bytes-like object'
            })
            continue

        if not key_regex.match(key):
            errors.append({
                key: "Label key '{}' does not match the regex {}".format(key, key_regex)
            })

        # value validation
        if not isinstance(value, str):
            errors.append({
                str(value): 'expected string or bytes-like object'
            })
            continue

        if not value_regex.match(value):
            errors.append({
                value: "Label key '{}' does not match the regex {}".format(value, value_regex)
            })

    if errors:
        raise ValidationError(errors)

