def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    if not hasattr(app, 'spec') or not hasattr(app.spec, 'manifest'):
        return

    spec = app.spec
    if not hasattr(spec.manifest, 'metadata') or spec.manifest.metadata is None:
        return

    if not hasattr(spec, 'manifest') or spec.manifest is None:
        return

    if not hasattr(spec.manifest, 'kind'):
        return

    if not hasattr(spec.manifest, 'apiVersion'):
        return

    kind = spec.manifest.kind
    api_version = spec.manifest.apiVersion

    # Check if custom observer schema is already specified for this kind
    if hasattr(app, 'observer') and hasattr(app.observer, 'schema'):
        existing_schema = app.observer.schema
        if existing_schema and hasattr(existing_schema, 'kinds'):
            if kind in existing_schema.kinds:
                return

    # Default observer schema: observe all fields
    default_observer = {
        'kinds': {
            kind: {
                'api_version': api_version,
                'fields': {
                    'spec': {}
                }
            }
        }
    }

    # Assign or update the observer schema in the app
    if not hasattr(app, 'observer') or app.observer is None:
        app.observer = {}

    if isinstance(app.observer, dict):
        if 'schema' not in app.observer or app.observer['schema'] is None:
            app.observer['schema'] = default_observer
        else:
            if isinstance(app.observer['schema'], dict):
                if 'kinds' not in app.observer['schema']:
                    app.observer['schema']['kinds'] = {kind: {
                        'api_version': api_version,
                        'fields': {
                            'spec': {}
                        }
                    }}
                elif kind not in app.observer['schema']['kinds']:
                    app.observer['schema']['kinds'][kind] = {
                        'api_version': api_version,
                        'fields': {
                            'spec': {}
                        }
                    }

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
