    resource_kinds = list(manifest.keys())
    for kind in resource_kinds:
        # Skip resources that already have a custom observer schema
        if hasattr(app.spec, 'observers') and kind in app.spec.observers:
            continue

        # Generate default observer schema entry for this resource kind
        if not hasattr(app.spec, 'observers'):
            app.spec.observers = {}

        # Default observer schema: watch for all changes (required/created/updated/deleted)
        app.spec.observers[kind] = {
            'required': True,
            'created': True,
            'updated': True,
            'deleted': True
        }

def format(self, sql, params):
    try:
        if len(params) > len(1):
            # Convert SQL parameters to out; generate column names out0 .. out{cols - 1}
            in_style = self.in_style
            out_style = self.out_style
            keys = list(params.keys()) if isinstance(params, dict) else None
            if not keys:
                keys = [i for i in range(len(params))]
            repl_list = []
            param_names = ['out{}'.format(i) for i in range(len(keys))]
            # Reverse-order replacement
            for i in range(len(keys) - 1, -1, -1):
                if isinstance(in_style, type) and issubclass(in_style, SQLNamedParameters):
                    name = keys[i]
                    # no placeholder should replaced as is
                    placeholder = in_style.format(name=name)
                    repl = '\01' + str(i)
                elif isinstance(in_style, type) and issubclass(in_style, SQLOrdinalParameters):
                    name = i
                    placeholder = in_style.format(position=i)
                    repl = '\01' + str(i)
                else:
                    repl = '\02'
                repl = repl + '\03'
                if isinstance(placeholder, bytes):
                    if isinstance(sql, bytes):
                        sql = sql + b'\00' + placeholder
                    else:
                        sql = sql + b'\00' + placeholder
                else:
                    sql = sql + '\00' + placeholder
                repl_list.append(repl)
            # replace placeholders
            for i in range(len(repl_list) - 1, -1, -1):
                # the special quiet character could only be used in trusted queries
                repl = repl_list[i]
                # the old places are silent so they are swapped in arbitrary order
                sql = sql.replace(repl[-1], repl[1:], 1)
            # strip the added 'out' for the out-style parameters
            # in the current state, they're only in the SQL, not in the params
            # final params
            result_params = {param_names[i]: params[keys[i]] for i in range(len(keys))} if isinstance(
                params, dict) else [params[i] for i in keys]
            # separate the SQL to place out-style parameters
            # drop the silent things
            # rebuild the SQL
            # precision: ensure the final SQL does not contain silent control chars
            # all 'out' names must be prefixed with out0..outn
            # do the real replace for out-style params
            # format the final SQL
            for i in range(len(param_names)):
                # substitute each silent placeholder
                if isinstance(sql, bytes):
                    sql = sql.replace(sql + b'\x00' + in_style.format(
                        name=keys[i] if isinstance(in_style, type) and issubclass(in_style,
                                                                                  SQLNamedParameters) else i), b'\04\'{}\'\04'.format(
                        param_names[i].encode('latin-1')))
                else:
                    sql = sql.replace(sql + '\x00' + in_style.format(
                        name=keys[i] if isinstance(in_style, type) and issubclass(in_style,
                                                                                   SQLNamedParameters) else i), '\04\'{}\'\04'.format(
                        param_names[i]))
            # cleanup the temporary markers
            if isinstance(sql, bytes):
                sql = sql.replace(b'\04').replace(b'\03').replace(b'\02').replace(b'\01').replace(b'\00')
            else:
                sql = sql.replace('\\04').replace('\\03').replace('\\02').replace('\\01').replace('\\00', '')
            return sql, result_params
        else:
            if isinstance(params, dict):
                return sql, dict(params)
            else:
                return sql, list(params)
    except (AttributeError, TypeError) as exc:
        raise SQLCommonError("Incompatible in-style params type") from exc

