    def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        if not isinstance(inventory, dict):
            raise SchemaFormatException("Inventory must be a dictionary", "")

        errors = []

        # If extract_spec_version is True, try to determine version from inventory
        spec_version = self.spec_version
        if extract_spec_version:
            type_value = inventory.get('type', None)
            if type_value is not None:
                # Check if type_value is a valid specification version
                valid_versions = getattr(self, 'valid_spec_versions', self.valid_spec_versions)
                if type_value in valid_versions:
                    spec_version = type_value
                else:
                    errors.append(SchemaFormatException(
                        "Invalid specification version: {!r}".format(type_value),
                        "type"
                    ))

        # Validate the inventory against the schema for the determined spec_version
        if not hasattr(self, 'schemata') or self.schemata is None:
            raise SchemaFormatException("No schemata available for validation", "")

        if spec_version not in self.schemata:
            raise SchemaFormatException(
                "No schema available for version: {!r}".format(spec_version),
                "type"
            )

        schema = self.schemata[spec_version]

        # Perform validation using the schema
        # Assuming schema has a validate method or we can use a validator
        try:
            validator = getattr(schema, 'validator', None)
            if validator is not None:
                result = validator(inventory)
                if isinstance(result, tuple):
                    valid, error_messages = result
                    if not valid:
                        for msg in error_messages:
                            errors.append(SchemaFormatException(msg, ""))
                else:
                    # If result is bool
                    if not result:
                        errors.append(SchemaFormatException("Inventory is invalid", ""))
            else:
                # Fallback: just check it's a dict
                if not isinstance(inventory, dict):
                    errors.append(SchemaFormatException("Inventory must be a dictionary", ""))
        except Exception as e:
            errors.append(SchemaFormatException("Validation error: {}".format(str(e)), ""))

        if errors:
            raise SchemaFormatException(
                "Inventory is invalid: " + "; ".join(str(e) for e in errors),
