    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Extract spec version if requested
    spec_version = self.spec_version
    if extract_spec_version:
        if isinstance(inventory, dict):
            inventory_type = inventory.get('type')
            if inventory_type is not None:
                if isinstance(inventory_type, str):
                    # Try to parse version from type string if it contains version info
                    # For example, types like "cluster-v1.2.3" or "v1"
                    parts = inventory_type.lower().split('-')
                    for part in parts:
                        if part.startswith('v'):
                            version_str = part[1:]
                            try:
                                spec_version = tuple(map(int, version_str.split('.')))
                            except ValueError:
                                # Invalid version format, fall back to self.spec_version
                                spec_version = self.spec_version
                            break
                    else:
                        # No version part found, fall back to self.spec_version
                        spec_version = self.spec_version
            else:
                spec_version = self.spec_version
        else:
            spec_version = self.spec_version

    # Validate the inventory based on the spec_version
    try:
        # Use the appropriate validator for the spec_version
        if hasattr(self, 'get_validator_for_version'):
            validator = self.get_validator_for_version(spec_version)
        else:
            # Assume there's a default validate method or we just level check the structure
            if not isinstance(inventory, dict):
                raise ValueError("Inventory must be a dictionary")
            return inventory

        if validator is not None:
            return validator.validate(inventory)
        else:
            # No specific validator found, do basic validation
            if not isinstance(inventory, dict):
                raise ValueError("Invalid inventory format: expected a dictionary")
            return inventory

    except TypeError as e:
        # Handle any type errors during validation
        raise ValueError(f"Inventory validation failed: {str(e)}")
