    def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        errors = []

        if not isinstance(prior, InventoryValidator):
            errors.append(f"Expected prior to be an InventoryValidator object, got {type(prior)}")
            return errors

        # Check that the time_ref of prior is earlier than or equal to self's time_ref
        try:
            if prior.time_ref > self.time_ref:
                errors.append(
                    f"Prior time_ref ({prior.time_ref}) is later than current time_ref ({self.time_ref})"
                )
        except Exception as e:
            errors.append(f"Error comparing time_ref values: {e}")

        # Check that the same data sources are present in prior
        if not self.data_sources:
            return errors  # If self has no data sources, nothing to check

        prior_sources = set(prior.data_sources)
        self_sources = set(self.data_sources)

        # All sources in self must exist in prior
        missing_sources = self_sources - prior_sources
        if missing_sources:
            errors.append(
                f"Data sources in current inventory not found in prior: {sorted(missing_sources)}"
            )

        # For each common source, check that the version in prior is earlier or same
        for source_name in self_sources:
            if source_name in prior_sources:
                try:
                    prior_version = prior._get_source_version(source_name)
                    self_version = self._get_source_version(source_name)
                    if prior_version is not None and self_version is not None:
                        if prior_version > self_version:
                            errors.append(
                                f"Data source '{source_name}' has a version ({prior_version}) in prior "
                                f"that is later than the current version ({self_version})"
                            )
                except Exception as e:
                    errors.append(f"Error comparing versions for source '{source_name}': {e}")

        return errors
