        if prior.end_version != prior.inventory:
            results.append(ValidatorResult('prior end version {0} expected version {1}'.
                                           format(prior.end_version, prior.inventory)))

        if prior.source != self.prior_source:
            results.append(ValidatorResult('prior source: {} vs prior source in life cycle name: {}'.
                                           format(prior.source, self.prior_source)))

        if prior.instances != self.prior_instances:
            results.append(ValidatorResult('instances in prior inventory: {} vs instances in life cycle name: {}'
                                           .format(prior.instances, self.prior_instances)))
        return results

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if not hasattr(inventory, 'state') or not hasattr(inventory.state, 'versioned'):
        return {}
    version_map = {}
    logical_paths = set()
    for vp in inventory.state.virtual_paths:
        if vp in logical_paths:
            continue
        logical_paths.add(vp)
        content_files = []
        version_exists = True
        current_version = version
        while current_version:
            if current_version not in inventory.versioned:
                version_exists = False
                break
            matches = inventory.versioned[current_version].logical_to_physical.get(vp, [])
            if matches:
                for content_file in matches:
                    if content_file not in content_files:
                        content_files.append(content_file)
                break
            elif not matches and current_version == version:
                break
            current_version = inventory.versioned[current_version].parent_version
        if version_exists and content_files:
            version_map[vp] = set(content_files)
    return version_map

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    result = {}
    if not inventory or not version:
        return result

    version_info = inventory.get(version)
    if not version_info:
        return result

    for logical_path, path_meta in version_info.items():
        if isinstance(path_meta, dict):
            content_files = path_meta.get('content_files', set())
            result[logical_path] = set(content_files)
        elif isinstance(path_meta, set):
            result[logical_path] = set(path_meta)
        else:
            result[logical_path] = set()
    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        raise ValueError("inventory must not be None")
    if version is None:
        raise ValueError("version must not be None")

    logical_path_map = {}

    if not isinstance(inventory, dict):
        return logical_path_map

    if version not in inventory:
        raise KeyError(f"version {version} not found in inventory")

    version_data = inventory[version]

    if not isinstance(version_data, list):
        return logical_path_map

    for entry in version_data:
        if not isinstance(entry, dict):
            continue

        logical_path = entry.get("logical_path")
        content_file = entry.get("content_file")
        if logical_path is not None and content_file is not None:
            if logical_path not in logical_path_map:
                logical_path_map[logical_path] = set()
            logical_path_map[logical_path].add(content_file)

    return logical_path_map

