def _eval_file(prefix, file_path):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    filename : str
        filename
    file_folder : str
        file folder

    Returns
    -------
    dict
    """
    if not file_path or not isinstance(file_path, str) or not file_path.strip():
        return {}

    import os
    ext = os.path.splitext(file_path)[1].lower()

    if ext in ['.jpg', '.jpeg', '.png', '.gif', '.bmp', '.svg', '.webp']:
        return {
            'type': 'rendition',
            'path': file_path
        }
    elif ext in ['.pdf', '.mp4', '.mp3', '.docx', '.doc', '.xlsx', '.pptx', '.txt', '.xml', '.json']:
        return {
            'type': 'asset',
            'path': file_path
        }
    else:
        return {
            'type': 'asset',
            'path': file_path
        }

def _eval_file(prefix, file_path):
    import os
    filename = os.path.basename(file_path)
    ext = os.path.splitext(filename)[1].lower()
    file_type = None
    if ext in ['.xml', '.jpg', '.jpeg', '.png', '.tif', '.tiff', '.gif', '.bmp']:
        if 'rendition' in filename.lower() or 'rendition' in prefix.lower():
            file_type = 'rendition'
        else:
            file_type = 'asset'
    if file_type:
        return {'type': file_type, 'name': filename, 'path': file_path}
    return {'type': None, 'name': filename, 'path': file_path}

