def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Since we do not know the structure of 'self', we implement a safe recursive
    # approach for common types (dict, list, tuple, set, frozenset) and fallback
    # to repr for others.

    def _pretty(obj, level, debug_flag):
        indent_str = '    ' * level

        if debug_flag:
            # In debug mode, we might want to include type info or memory address
            prefix = f"[{type(obj).__name__}] "
        else:
            prefix = ""

        if obj is None:
            return prefix + 'None'

        if isinstance(obj, bool):
            return prefix + str(obj)

        if isinstance(obj, (int, float)):
            return prefix + repr(obj)

        if isinstance(obj, (str, bytes)):
            return prefix + repr(obj)

        if isinstance(obj, dict):
            if not obj:
                return prefix + '{}'
            items = []
            for k, v in obj.items():
                key_str = _pretty(k, level, debug_flag)
                val_str = _pretty(v, level + 1, debug_flag)
                items.append(f"{key_str}: {val_str}")
            inner = ',\n'.join(items)
            return prefix + '{\n' + '    ' * (level + 1) + inner + ',\n' + '    ' * level + '}'

        if isinstance(obj, (list, tuple, set, frozenset)):
            if not obj:
                return prefix + ('[]' if isinstance(obj, (list, tuple)) else 'set()')

            # For sets, we sort if elements support comparison for deterministic output, 
            # but repr is safer for mixed types. Let's just use repr for elements 
            # or recurse. For sets, recursion depth might be tricky with unhashable 
            # elements inside, but standard pretty printers handle basic types.
            items = []
            elements = sorted(obj) if isinstance(obj, (set, frozenset)) else obj
            for elem in elements:
                items.append('    ' * (level + 1) + _pretty(elem, level, debug_flag))

            if isinstance(obj, tuple):
                opening, closing = '(', ')'
                # Tuple with single element needs comma
                if len(obj) == 1:
                    inner = ','
                else:
                    inner = ',\n'.join(items) + ',\n' if items else ''
                # Ensure correct indentation for closing paren
                return prefix + '(\n' + '    ' * (level + 1) + [('    ' * (level + 1) + str(i) for i in []] or items) + '\n' if False else None # This logic is getting complex, let's simplify below

            # Simplified approach for lists, tuples, sets
            el = list(obj)
            if not el:
                if isinstance(obj, (list,)):
                    return prefix + '[]'
                elif isinstance(obj, tuple):
                    return prefix + '()'
                else:
                    return prefix + 'set()'

            formatted_items = []
            for item in el:
                formatted_items.append(_pretty(item, level + 1, debug_flag))

            joined = ',\n'.join(formatted_items)
            if isinstance(obj, (list,)):
                if len(el) == 0:
                    return prefix + '[]'
                return prefix + '[\n' + '    ' * (level + 1).replace('    ', '    ') + joined + ',\n' + '    ' * level + ']'
            elif isinstance(obj, tuple):
                if len(el) == 0:
                    return prefix + '()'
                if len(el) == 1:
                    return prefix + '(' + formatted_items[0] + ',)'
                return prefix + '(\n' + ',\n'.join('    ' * (level + 1) + x for x in formatted_items) + ',\n' + '    ' * level + ')'
            else: # set/frozenset
                if len(el) == 0:
                    return prefix + 'set()'
                return prefix + '{' + ', '.join(formatted_items) + '}'

        # Fallback to repr for other objects
        return prefix + repr(obj)

    return _pretty(self, indent, debug)

