def _fromutc(self, dt):
    naive = dt.replace(tzinfo=None)
    loc_dt = self._naive_from_localtime(naive)
    if loc_dt is None:
        return self.localize(naive, is_dst=False)
    if loc_dt > naive:
        loc_dst = self._naive_to_localtime(naive + timedelta(days=1))
        if loc_dst is not None and loc_dst > loc_dt:
            # We are in a gap
            return super(TimeZone, self).fromutc(dt)
    return self.localize(naive, is_dst=None)

