def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess

    if not commands:
        return None

    if isinstance(commands, str):
        commands = [commands]
    elif not isinstance(commands, (list, tuple)):
        commands = [str(commands)]

    if args is None:
        args = []
    elif isinstance(args, str):
        args = args.split()
    elif not isinstance(args, (list, tuple)):
        args = [str(args)]

    full_command = list(commands) + list(args)

    if verbose:
        print("Running command:", " ".join(full_command))

    try:
        kw = {
            'stdin': subprocess.PIPE,
            'stdout': subprocess.PIPE,
            'stderr': subprocess.PIPE,
            'env': env,
        }
        if cwd is not None:
            kw['cwd'] = cwd

        proc = subprocess.Popen(full_command, **kw)
        stdout, stderr = proc.communicate()

        if proc.returncode != 0:
            raise subprocess.CalledProcessError(proc.returncode, full_command, output=stdout, stderr=stderr)

        if hide_stderr:
            return (stdout, "")
        else:
            return (stdout, stderr)

    except subprocess.CalledProcessError as e:
        if verbose:
            print("Command failed with return code:", e.returncode)
            if e.stderr:
                print("stderr:", e.stderr)
        raise
    except Exception as e:
        if verbose:
            print("Exception while running command:", str(e))
