def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    total_issues = 0

    # Walk all storage objects under the root
    try:
        for path in self.walk_paths():
            num_objects += 1
            is_good = True

            if validate_objects:
                obj_ok, obj_details = self.validate_object(path)
                if not obj_ok:
                    is_good = False
                    total_issues += 1
                    if show_warnings:
                        self.print_warning("Object validation failed for {}: {}".format(path, obj_details))

            if check_digests:
                digest_ok, digest_details = self.check_digests(path)
                if not digest_ok:
                    is_good = False
                    total_issues += 1
                    if show_warnings:
                        self.print_warning("Digest check failed for {}: {}".format(path, digest_details))

            if is_good:
                good_objects += 1

    except Exception as e:
        if show_warnings:
            self.print_warning("Unexpected error during hierarchy validation: {}".format(e))

    return num_objects, good_objects

