def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version or not isinstance(version, str):
        return None

    parts = version.split('.')

    # Check if the version is in a valid format (all parts should be digits)
    for part in parts:
        if not part.isdigit():
            return None

    # Convert to integers
    nums = [int(part) for part in parts]

    # Increment the last part
    nums[-1] += 1

    # Reconstruct the version with the same leading zero pattern
    result_parts = []
    for i, num in enumerate(nums):
        # If any part was zero-prefixed, maintain that format
        if i < len(parts) and parts[i].startswith('0') and len(parts[i]) > 1:
            result_parts.append(f'{num:0{len(parts[i])}d}')
        else:
            result_parts.append(str(num))

    return '.'.join(result_parts)

