def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    if os.path.isfile(path):
        return 'file'

    # Check for Namaste file first
    namaste_file = os.path.join(path, '0=namaste')
    if os.path.exists(namaste_file):
        try:
            with open(namaste_file, 'r') as f:
                namaste = f.read()
            if 'ocfl_version' in namaste:
                # Need to check for version 1.0 for root
                if 'ocfl_version' in namaste:
                    # Simple check, could be more robust
                    if 'version' in namaste:
                        return 'root'
            # If there's a Namaste but it's not identifiable as root, it could be object?
            # Actually, Namaste can be in both. Let's look for version.
            if 'namaste' in namaste and 'version' in namaste:
                 # More specific check needed, but let's assume valid Namaste in root is root
                 return 'root'
        except Exception as e:
            return f'error: could not read namaste file: {str(e)}'

    # Check for Inventory
    inventory_file = os.path.join(path, '1=inventory.json')
    if os.path.exists(inventory_file):
        return 'object'

    # For robustness, check for any 0=namaste
    entries = os.listdir(path)
    for entry in entries:
        if entry.startswith('0=namaste'):
            namaste_full = os.path.join(path, entry)
            try:
                with open(namaste_full, 'r') as f:
                    content = f.read()
                # OCFL Storage Root Namastes typically contain version info
                if 'ocfl_version' in content:
                    return 'root'
            except Exception:
                pass

    # If it's a directory but not root or object
    return 'error: not an OCFL directory'

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    if os.path.isfile(path):
        return 'file'
    elif os.path.isdir(path):
        # Check for OCFL Storage Root: must contain "0root" or "1root" files
        for item in os.listdir(path):
            if item.startswith('0=') or item.startswith('1='):
                # A valid OCFL root has exactly one 1root file and optional 0root files
                # Simplified: if there's any 0= or 1= file, treat as root candidate
                # But to be more precise, a storage root has a "0root" or "1root" at top
                count_0 = 0
                count_1 = 0
                for item in os.listdir(path):
                    if item.startswith('0='):
                        count_0 += 1
                    elif item.startswith('1='):
                        count_1 += 1
                if count_1 >= 1:
                    return 'root'
                elif count_0 >= 1:
                    # Could be a root with only 0= files (less common)
                    return 'root'
                # If no 0= or 1=, not a root
        # Check for OCFL Object: must have directory structure like "0=..." or contain object versions
        # An OCFL object directory typically contains "0=version" or version directories
        for item in os.listdir(path):
            if item.startswith('0=') or item.startswith('v'):
                # Check if this looks like an object: it should have a structure
                # Simplified: if it has 0= files, treat as object
                return 'object'
        return 'unknown: not an OCFL root or object'
    else:
        return 'error: path does not exist'

