            result[key] = value
    return list(result.items())

def deep_merge_nodes(nodes):
    if not nodes:
        return []

    # Build a list of entries, using the key's value (or a unique placeholder) for ordering/dedup key
    updated_nodes = []
    seen_keys = {}  # key_string -> index in updated_nodes

    for key, value in nodes:
        # Use the ScalarNode's value as the merge key; fall back to id if no value attribute (defensive)
        try:
            key_val = getattr(key, 'value', None)
        except Exception:
            key_val = None

        use_key = key_val if key_val is not None else str(id(key))
        key_str = str(use_key)

        if key_str in seen_keys:
            existing_idx = seen_keys[key_str]
            existing_key, existing_value = updated_nodes[existing_idx]

            # If both are MappingNode, recursively deep-merge their value lists
            # ruamel.yaml.nodes has MappingNode and ScalarNode available; we duck-check by type name
            # to avoid import dependency.
            try:
                existing_is_mapping = (type(existing_value).__name__ == 'MappingNode')
                incoming_is_mapping = (type(value).__name__ == 'MappingNode')
            except Exception:
                existing_is_mapping = False
                incoming_is_mapping = False

            if existing_is_mapping and incoming_is_mapping:
                # Merge the inner lists using the same function
                # Map value of a MappingNode is its 'value' attribute (list of tuples)
                try:
                    existing_inner = existing_value.value
                    incoming_inner = value.value
                except Exception:
                    # If any issue, last wins
                    existing_inner = []
                    incoming_inner = []

                merged_inner = deep_merge_nodes(existing_inner + incoming_inner)
                # Replace the existing node’s value list with merged result
                try:
                    existing_value.value = merged_inner
                except Exception:
                    # If we can’t set, create a new tuple with merged value
                    updated_nodes[existing_idx] = (existing_key, value)
            else:
                # Last wins for non-Mapping conflicts
                updated_nodes[existing_idx] = (existing_key, value)
        else:
            seen_keys[key_str] = len(updated_nodes)
            updated_nodes.append((key, value))

    return updated_nodes

def deep_merge_nodes(nodes):
    merged = {}
    for key, value in nodes:
        key_str = key.value
        if key_str not in merged:
            merged[key_str] = (key, value)
        else:
            existing_key, existing_value = merged[key_str]
            if not hasattr(existing_value, 'value'):
                merged[key_str] = (key, value)
            elif not hasattr(value, 'value'):
                merged[key_str] = (key, value)
            elif existing_value.__class__ == value.__class__:
                merged_value = deep_merge_nodes(existing_value.value + value.value)
                if hasattr(existing_value, 'items'):
                    merged_value = existing_value.__class__(existing_value.tag, merged_value)
                merged[key_str] = (existing_key, merged_value)
            else:
                merged[key_str] = (key, value)
    return [kv for _, kv in merged.items()]

