            # But typically parsing errors for known/unknown args shouldn't raise general exceptions
            # in a way that crashes the whole process if we are just trying to claim args.
            # However, strict parsing might be desired. Let's assume we just skip if it fails.
            continue

    return parsed, remaining

def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    """
    try:
        merged = {}
        for key, value in nodes:
            if not isinstance(key, (str, int, float)):
                key_val = getattr(key, 'value', None)
            else:
                key_val = key

            if key_val in merged:
                existing_key, existing_value = merged[key_val]
                from ruamel.yaml.nodes import MappingNode
                if isinstance(existing_value, MappingNode) and isinstance(value, MappingNode):
                    merged_value_nodes = deep_merge_nodes(existing_value.value + value.value)
                    existing_value.value = merged_value_nodes
                else:
                    merged[key_val] = (key, value)
            else:
                merged[key_val] = (key, value)
        return list(merged.values())
    except Exception as e:
        raise e

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    if not nodes:
        return nodes

    # Use a dictionary to group nodes by their key's value
    key_to_nodes = {}
    for key, value in nodes:
        # Use the key's value as the identifier for grouping
        key_value = key.value
        if key_value in key_to_nodes:
            key_to_nodes[key_value].append((key, value))
        else:
            key_to_nodes[key_value] = [(key, value)]

    # Start with the first node in the list
    merged_nodes = []
    for key_value, node_list in key_to_nodes.items():
        current_key = node_list[0][0]
        current_value = node_list[0][1]

        # If there are more than one node with this key, merge them
        if len(node_list) > 1:
            # If both values are MappingNode, recursively merge them
            if all(isinstance(node[1], MappingNode) for node in node_list):
                merged_value = MappingNode(tag='tag:yaml.org,2002:map', value=[])
                # Merge all the mapping nodes
                for _, value in node_list:
                    for sub_key, sub_value in value.value:
                        merged_value.value.append((sub_key, sub_value))
                current_value = merged_value
            else:
                # If not all values are MappingNode, use the last one
                current_value = node_list[-1][1]

        merged_nodes.append((current_key, current_value))

    return merged_nodes

