            # to allow other subparsers to potentially claim some arguments or to let the main parser handle it.
            # In this context, we treat the failure as claiming no arguments and leaving the rest for the main parser.
            pass

    return (parsed_arguments, remaining_arguments)

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    if not isinstance(response, list) or not isinstance(max_results, int) or max_results <= 0:
        return iter([])
    for i in range(0, len(response), max_results):
        yield response[i:i + max_results]

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    if not size or not isinstance(size, str):
        raise ValueError("Input must be a non-empty string")

    size = size.strip()

    multipliers = {'B': 1, 'K': 1000, 'M': 10**6, 'G': 10**9, 'T': 10**12, 'P': 10**15}

    if not size:
        return 0

    unit = size[-1].upper()

    if unit not in multipliers:
        # If the last character is not a valid unit suffix, treat it as part of the number
        # But first let's check if it's a number
        try:
            return int(float(size))
        except ValueError:
            raise ValueError(f"Invalid size format: {size}")

    try:
        value = float(size[:-1])
    except ValueError:
        # If removing the last char makes it invalid, try whole string as number
        try:
            return int(float(size))
        except ValueError:
            raise ValueError(f"Invalid size format: {size}")

    return int(value * multipliers[unit])

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    combined = {}
    for d in dicts:
        for key, value in d.items():
            if key in combined:
                combined[key] += value
            else:
                combined[key] = value
    return combined

