def vertex3tuple(vertices):
    """return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::

        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3tuples
        #A    B    C    D  -> of vertices
    """
    try:
        if vertices is None:
            return []
        if not hasattr(vertices, "__iter__") or isinstance(vertices, (str, bytes)):
            return [(vertices, vertices, vertices)]
        lst = list(vertices)
    except Exception:
        return []
    try:
        n = len(lst)
    except Exception:
        return []
    if n == 0:
        return []
    if n == 1:
        return [(lst[0], lst[0], lst[0])]
    if n == 2:
        return [
            (lst[0], lst[1], lst[0]),
            (lst[1], lst[0], lst[1]),
        ]
    out = []
    # For vertex i: previous, current, next with wraparound
    for i in range(n):
        prev_idx = (i - 1) % n
        next_idx = (i + 1) % n
        out.append((lst[prev_idx], lst[i], lst[next_idx]))
    return out
