def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    if base == 0:
        if string == "":
            return 0
        raise ValueError("alphabet cannot be empty")

    # Build a mapping from each character in alphabet to its index (value)
    char_to_value = {c: i for i, c in enumerate(alphabet)}

    result = 0
    for c in string:
        result = result * base + char_to_value.get(c, None)
        if char_to_value.get(c) is None:
            raise ValueError(f"Character '{c}' not found in alphabet")

    return result

