                        # Check if next char is a quote or backslash
                        if pos + 1 < n and s[pos+1] == '"':
                            chunk += '"'
                            pos += 2
                        elif pos + 1 < n and s[pos+1] == '\\':
                            chunk += '\\'
                            pos += 2
                        elif pos + 1 < n:
                            # Backslash followed by non-quote, treat backslash literally
                            chunk += char
                            pos += 1
                        else:
                            chunk += char
                            pos += 1
                    elif char == '"':
                        in_quotes = False
                        pos += 1
                    else:
                        chunk += char
                        pos += 1
                else:
                    if char.isspace():
                        break
                    elif char == '"':
                        in_quotes = True
                        pos += 1
                    else:
                        chunk += char
                        pos += 1

            # If we exited the inner loop because of whitespace or end of string,
            # and we are still in quotes, that's an unterminated quote.
            # On Windows, this usually results in the rest of the string being part of the token.
            # But our loop above handles the consumption.
            # If the string ended while in_quited was True, the loop would have exited when pos >= n.

            if chunk:
                result.append(chunk)
            else:
                # If chunk is empty, it means we had empty quotes or just whitespace
                # In Windows cmd, empty quotes might produce an empty argument
                # But typically, if there are no chars between quotes, it's an empty arg.
                # However, our loop logic: if we enter inner loop and immediately see quote,
                # in_quotes becomes True, then we see closing quote, in_quotes becomes False,
                # chunk is still empty. The outer while continues.
                # If there are multiple spaces, we skip them.
                # It is rare to get an empty chunk unless there were empty quotes " "".
                # Let's add empty string if we actually processed something (like empty quotes).
                # To be safe and match basic splitting, we only append non-empty chunks 
                # unless we explicitly handled empty quotes.
                # For simplicity and robustness against common cases, we append if 
                # the iteration advanced. But given the structure, an empty chunk 
                # effectively means "skip this token".
                pass

        return result

    else:
        raise ValueError("Invalid platform value: " + str(platform))

