    subprocess.run(req, check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)

    # If filename is specified, look for it in the extraction directory
    if filename is not None:
        # Iterate through extracted folders/files to find the one with the specified name
        for root, dirs, files in os.walk(extr_dir):
            for d in dirs:
                if d == filename:
                    return f"file://{os.path.join(root, d)}"
            # Also check files (unlikely, but for completeness)
            for f in files:
                if f == filename:
                    return f"file://{os.path.join(root, f)}"
        raise ValueError(f"Filename {filename} not found in extracted archive")
    else:
        # Return the main extraction directory
        return f"file://{extr_dir}"
