from pathlib import PosixPath, Path

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"Archive path does not exist: {archive_path}")

    tmp_dir = Path(tmp_path) / "repo_archive"
    if tmp_dir.exists():
        shutil.rmtree(tmp_dir)
    tmp_dir.mkdir(parents=True, exist_ok=True)

    # Determine the archive format and extract accordingly
    archive_path = Path(archive_path)

    if archive_path.suffix in ('.tar', '.tar.gz', '.tgz', '.tar.bz2', '.tbz2'):
        with tarfile.open(archive_path, 'r:*') as tar:
            try:
                tar.extractall(tmp_dir)
            except Exception as e:
                raise ValueError(f"Failed to extract archive: {str(e)}")
    elif archive_path.suffix == '.zip':
        with zipfile.ZipFile(archive_path, 'r') as zip_ref:
            try:
                zip_ref.extractall(tmp_dir)
            except Exception as e:
                raise ValueError(f"Failed to extract archive: {str(e)}")
    else:
        # Try to detect using file extension or content
        suffix = archive_path.suffix.lower()
        if suffix in ('.tgz',):
            with tarfile.open(archive_path, 'r:gz') as tar:
                tar.extractall(tmp_dir)
        elif suffix in ('.tbz2',):
            with tarfile.open(archive_path, 'r:bz2') as tar:
                tar.extractall(tmp_dir)
        else:
            # Fallback: try tar first, then zip
            try:
                with tarfile.open(archive_path, 'r:*') as tar:
                    tar.extractall(tmp_dir)
            except tarfile.TarError:
                try:
                    with zipfile.ZipFile(archive_path, 'r') as zip_ref:
                        zip_ref.extractall(tmp_dir)
                except zipfile.BadZipFile:
                    raise ValueError(f"Unsupported archive format: {archive_path}")

    # Determine the top-level directory or the specific file/directory of interest
    if filename:
        # Look for the specific filename in the extracted directory
        target_path = None
        for item in tmp_dir.rglob(filename):
            target_path = item
            break
        if target_path is None:
            raise ValueError(f"File or directory '{filename}' not found in extracted archive")
    else:
        # Find the top-level directory or the single item extracted
        items = list(tmp_dir.iterdir())
        if len(items) == 1:
            target_path = items[0]
        else:
            # If multiple items, find the common parent or use tmp_dir itself
            # Look for a single directory that contains .git
            target_path = tmp_dir
            for item in items:
                if item.is_dir() and (item / '.git').exists():
                    target_path = item
                    break

    if target_path is None:
        target_path = tmp_dir

    # Ensure the path has a valid git repository
    if not (target_path / '.git').exists():
        # Try to initialize git repository if not exists
        try:
            subprocess.run(['git', 'init'], cwd=str(target_path), check=True, capture_output=True)
        except subprocess.CalledProcessError as e:
            raise ValueError(f"Failed to initialize git repository in {target_path}: {str(e)}")

    # Check if there's a remote origin already
    try:
        subprocess.run(['git', 'remote', 'add', 'origin', f'file://{target_path}'], cwd=str(target_path), check=True, capture_output=True)
    except subprocess.CalledProcessError:
        # Remote might already exist, try updating
        try:
            subprocess.run(['git', 'remote', 'set-url', 'origin', f'file://{target_path}'], cwd=str(target_path), check=True, capture_output=True)
        except subprocess.CalledProcessError as e:
            raise ValueError(f"Failed to set origin URL: {str(e)}")

    return f"file://{target_path}"

