) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not archive_path or not isinstance(archive_path, str):
        raise ValueError("archive_path must be a non-empty string")

    if tmp_path is None:
        tmp_path = "/tmp"

    tmp_path = PosixPath(tmp_path) if isinstance(tmp_path, str) else tmp_path
    tmp_path = tmp_path.absolute()
    if not tmp_path.exists() or not tmp_path.is_dir():
        raise OSError(f"Temporary path does not exist or is not a directory: {tmp_path}")

    base_name = os.path.basename(archive_path)
    if not base_name:
        raise ValueError("Could not determine base name for archive")

    # Determine if we should use the provided filename (for multi-entry archives or specific pick)
    if filename is None:
        target_file = base_name
    else:
        target_file = os.path.basename(filename)
        if not target_file:
            raise ValueError("filename must be a non-empty string")

    extract_dir = tempfile.mkdtemp(dir=str(tmp_path), prefix="prep_repo_")

    try:
        # Use 7z if available for broad compatibility, otherwise fallback to tar/cp/unzip
        decommand = None
        try:
            subprocess.run(["7z", "ls"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, check=True)
            decommand = ["7z"]
        except (subprocess.CalledProcessError, FileNotFoundError, OSError):
            pass

        if decommand:
            subprocess.run(decommand + ["x", "-y", f"-o{extract_dir}", str(archive_path)], check=True)
        else:
            # Fallback to tar
            if archive_path.endswith((".tar", ".tar.gz", ".tgz", ".tar.bz2", ".tar.xz")):
                cmd = ["tar"]
                if archive_path.endswith((".tar.gz", ".tgz")):
                    cmd.append("-z")
                elif archive_path.endswith(".tar.bz2"):
                    cmd.append("-j")
                elif archive_path.endswith(".tar.xz"):
                    cmd.append("-J")
                cmd += ["-xf", str(archive_path), "-C", str(extract_dir)]
                subprocess.run(cmd, check=True)
            elif archive_path.endswith(".zip"):
                cmd = ["unzip", "-q", str(archive_path), "-d", str(extract_dir)]
                subprocess.run(cmd, check=True)
            else:
                raise ValueError(f"Unsupported archive type for file: {archive_path}")

        target_path = extract_dir
        if filename is not None:
            # Look for the subfile inside
            if os.path.isdir(os.path.join(extract_dir, target_file)):
                continue # maybe top level?
            candidate = os.path.join(extract_dir, target_file)
            if os.path.exists(candidate):
                target_path = candidate
            else:
                # Search inside
                found = None
                for root, dirs, files in os.walk(extract_dir):
                    if target_file in files:
                        found = os.path.join(root, target_file)
                        break
                    if target_file in dirs:
                        # Take the first dir match
                        found = os.path.join(root, target_file)
                        break
                if found is None:
                    raise FileNotFoundError(f"File {target_file} not found inside extracted archive: {extract_dir}")
                target_path = found

        # Fix permissions for uv to be able to read?
        if os.path.isdir(target_path):
            pass
        furl = PosixPath(target_path).absolute().as_uri()
        return furl
    finally:
        # Cleanup temp extract directory immediately
        import shutil
        try:
            shutil.rmtree(extract_dir, ignore_errors=True)
        except Exception:
            pass
