def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        # Attempt to resolve the host to an IP address
        addr_infos = socket.getaddrinfo(host, None, socket.AF_INET, socket.SOCK_STREAM)
        ips = {info[4][0] for info in addr_infos}
    except socket.gaierror:
        # If resolution fails, it's not a valid local host
        return False
    except Exception:
        # In case of any other unexpected error during resolution
        return False

    # Check if any of the resolved IPs are known localhost addresses
    return any(ip in ('127.0.0.1', '::1') for ip in ips)

