def make_find_paths(find_paths):
    '''
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    '''
    if not isinstance(find_paths, (list, tuple)):
        raise TypeError("find_paths must be a list or tuple of strings")

    transformed = []
    for path in find_paths:
        if not isinstance(path, str):
            raise TypeError(f"Each path fragment must be a string, got {type(path)}")
        if not path:
            continue
        if '*' in path or '?' in path or '[' in path:
            transformed.append(path)
        else:
            # Check if this is a path with a protocol prefix (contains a colon and not at the start as in Windows paths)
            # More robust check: if it contains a colon, and the part before the colon is non-empty and appears to be a scheme
            # But per the example, 'pp:root/somedir' is passed through. We can check if it matches a pattern like 'scheme:...'
            # where scheme does not contain '/' and the colon is not the first char.
            has_scheme = re.match(r'^[a-zA-Z][a-zA-Z0-9+\-.\-]*:', path)
            if has_scheme:
                transformed.append(path)
            else:
                transformed.append(f"sh:**/*{path}*/**")
    return transformed

def make_find_paths(find_paths):
    regex_pattern = re.compile(r'(.*[^*])?/?([^/*]*)/$')
    return ['**'.join(re.match(r'([^/]*)/([^/]*)/(.*)', part).groups()) if re.match(r'([^/]*)/([^/]*)/(.*)', part) else part for part in find_paths]

