            full_cmd_str.append(item.decode())
        else:
            full_cmd_str.append(str(item))

    if verbose:
        print("Running: {}".format(" ".join(full_cmd_str)))

    kwargs = {}
    if cwd is not None:
        kwargs["cwd"] = cwd
    if env is not None:
        kwargs["env"] = env
    if hide_stderr:
        kwargs["stderr"] = subprocess.DEVNULL

    try:
        result = subprocess.run(full_cmd_str, check=True, **kwargs)
        return result
    except subprocess.CalledProcessError as e:
        raise
    except Exception as e:
        raise
