def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not commands:
        return None

    # If commands is a string, split it
    if isinstance(commands, str):
        command_parts = commands.split()
    else:
        command_parts = commands

    # Combine with args
    if args:
        command_parts = command_parts + [str(arg) for arg in args]

    # Build the full command list
    full_command = command_parts

    # Prepare the subprocess call
    try:
        process = subprocess.Popen(
            full_command,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE if hide_stderr else None
        )

        stdout, stderr = process.communicate()

        if verbose:
            if stdout:
                print(stdout.decode('utf-8', errors='replace'))
            if stderr and not hide_stderr:
                print(stderr.decode('utf-8', errors='replace'))

        if process.returncode != 0:
            raise subprocess.CalledProcessError(process.returncode, full_command, output=stdout, stderr=stderr)

        return stdout
    except Exception as e:
        raise e

