def find_roots(graph, prop, roots=None):
    if roots is None:
        roots = set()
    for parent in graph.subjects(prop, None):
        if parent in roots:
            continue
        roots.add(parent)
        # Find the parent's parent
        for grandparent in graph.subjects(prop, parent):
            if grandparent not in roots:
                find_roots(graph, prop, roots)
    return roots

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:

    if roots is None:
        roots = set()

    for child, _prop, parent in graph.triples((None, prop, None)):
        if parent not in roots:
            roots.add(parent)

    for child, _prop, parent in graph.triples((None, prop, None)):
        if child not in roots and parent in roots:
            roots.discard(child)

    return roots

