                        return value
                    # Pattern matches ${VAR} or $VAR
                    env_pattern = re.compile(r'\$\{([A-Za-z_][A-Za-z0-9_]*)\}|\$([A-Za-z_][A-Za-z0-9_]*)')
                    content = env_pattern.sub(replace_env, content)

