def scale(self, other=None):
    if other is None:
        return self._scale

    if not isinstance(other, (int, float)):
        raise TypeError("scale other must be a number")
    if other <= 0:
        raise ValueError("scale other must be positive")

    if self._scale is None or self._scale == 0:
        raise ValueError("unknown or zero scale; cannot rescale")

    if self.coords is None:
        raise ValueError("graph has no coordinates")

    if self.coords.ndim < 1:
        raise ValueError("graph must have at least one coordinate axis")

    last_axis = self.coords.shape[-1] - 1
    last_coords = self.coords[..., last_axis]
    last_errs = None
    if self.erro is not None:
        last_errs = self.erro[..., last_axis]

    factor = other / self._scale
    last_coords *= factor
    if last_errs is not None:
        last_errs *= factor

    self._scale = other
    return self._scale

