                  field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_content: bin_content
    coordinate_labels = ("left", "right", "middle")
    if get_coordinate not in coordinate_labels:
        raise ValueError(
            "'get_coordinate' must be one of {} but was '{}'".format(coordinate_labels, get_coordinate))
    x_field, y_field = field_names
    graph = {}
    for start, end in zip(hist.bins[:-1], hist.bins[1:]):
        if not (start < end):
            raise ValueError('Histogram bins must be in ascending order')
        x_coordinate = (start + end) / 2 if get_coordinate == "middle" else (
            start if get_coordinate == "left" else end)
        y_value = make_value(hist.bins[start:end].sum())
        graph[x_coordinate] = (x_coordinate, y_value)
    y_scale = hist.scale if scale is True else scale
    return {x_field: [x for x, y in graph.values()], y_field: [y for x, y in graph.values()], "scale": y_scale}

