    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Check that the interface and candidate are the right type
    if not hasattr(iface, '__iter__'):
        raise TypeError('Not a valid interface: %r' % iface)
    if not hasattr(candidate, '__iter__'):
        raise TypeError('Not a valid candidate: %r' % candidate)

    # If the interface and candidate are the same, we do nothing else
    if iface == candidate:
        return

    # If tentative mode is enabled, we want to make sure that every
    # method from the interface is either present in the candidate, or
    # inheritable from a candidate's parent class
    if tentative:
        for base in candidate.__bases__:
            if isinstance(base, iface):
                return
        # If we don't find the interface as a base class, we need to
        # check the candidate's methods
        for method in iface:
            if not hasattr(candidate, method):
                return
        return

    # If tentative mode is disabled, we want to check that the candidate
    # provides all the methods from the interface
    for method in iface:
        if not hasattr(candidate, method):
            raise TypeError('Class %r does not provide method %r from interface %r' %
                            (candidate, method, iface))
