def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        if not callable(explicit_mc):
            raise TypeError("__metaclass__ must be a callable (e.g., a type)")
        return explicit_mc

    metaclasses = set()
    for base in bases:
        if base is None:
            continue
        metaclass = type(base)
        metaclasses.add(metaclass)

    if not metaclasses:
        return type

    if len(metaclasses) == 1:
        return metaclasses.pop()

    # Check for a winner among the metaclasses
    winner = None
    remaining = list(metaclasses)
    for i, mc1 in enumerate(remaining):
        for mc2 in remaining[i+1:]:
            if issubclass(mc1, mc2):
                winner = mc2
                break
            elif issubclass(mc2, mc1):
                winner = mc1
                break
            else:
                raise TypeError("metaclasses conflict: not a single winner")
        if winner is not None:
            break

    if winner is None:
        # Fallback: pick the first one? Or raise? In typical Python, if no conflict via subclass relationship, it's an error.
        # But here we just picked all metaclasses. If they are unrelated, it's an error.
        # Let's re-evaluate. If multiple distinct metaclasses and none is subclass of another -> TypeError
        raise TypeError("metaclasses conflict: not a single winner")

    return winner
