def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if not bases:
        raise ValueError("At least one base class is required")

    # Start with the most derived metaclass found among the bases.
    # In Python, the metaclass of a class is the most derived metaclass
    # of its bases and any explicitly declared metaclass.

    def _get_metaclass(cls):
        """Safely get the metaclass of a class or a tuple of classes.

        If cls is a tuple, we need to find the most derived metaclass among them.
        However, for non-tuple types, type(cls) is the metaclass.
        For tuples, we can call type() on the tuple? No, that's not how metaclass resolution works for tuples in class creation.
        Actually, if bases is a tuple, we need to look at each base.
        """
        if isinstance(cls, tuple):
            # If the input to type() was a tuple (unusual for bases in this context,
            # but let's handle it if bases is a tuple of classes), 
            # the metaclass is determined by the most derived metaclass of the items.
            # However, the function signature implies bases is a tuple/list of base classes.
            # The parameter name is 'bases' (plural).
            # So we should iterate over the bases.
            mc_list = [_get_metaclass(b) for b in cls if isinstance(b, type)]
            if not mc_list:
                return type
            # Find the most derived metaclass
            current_mc = mc_list[0]
            for mc in mc_list[1:]:
                if isinstance(mc, type(current_mc)):
                    current_mc = mc
                elif isinstance(current_mc, type(mc)):
                    pass # current_mc is more derived
                else:
                    raise TypeError("metaclass conflict: the metaclass of the derived type must be a (non-strict) subclass of the metaclasses of all its bases")
            return current_mc
        elif isinstance(cls, type):
            return type(cls)
        else:
            return type

    # The input 'bases' is likely a tuple or list of base classes.
    # The 'explicit_mc' is an optional metaclass.

    # Filter bases to only include types
    valid_bases = [b for b in bases if isinstance(b, type)]

    if not valid_bases:
        # If no valid bases, but explicit_mc is provided, use it.
        # Otherwise, default to type.
        if explicit_mc is not None and isinstance(explicit_mc, type):
            if not issubclass(explicit_mc, type):
                raise TypeError("metaclass %r must be a subclass of type" % (explicit_mc,))
            return explicit_mc
        return type

    # Determine the metaclass from the bases
    base_mc = _get_metaclass(tuple(valid_bases))

    # If there is an explicit metaclass, it must be a subclass of the base metaclass
    # or we get a conflict.
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("metaclass must be a type")
        if not issubclass(explicit_mc, type):
            raise TypeError("metaclass %r must be a subclass of type" % (explicit_mc,))

        if not issubclass(explicit_mc, base_mc):
            raise TypeError("metaclass conflict: the metaclass of the derived type must be a (non-strict) subclass of the metaclasses of all its bases")
        return explicit_mc

    return base_mc

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    metaclass = None
    if explicit_mc is not None:
        # check for subtypes of type and explicit_mc
        try:
            make_mro([type, explicit_mc])
            metaclass = explicit_mc
        except (TypeError, AttributeError):
            raise TypeError('Error when trying to convert meta to class type:')
    if metaclass is None:
        bestcls = type
        for base in bases:
            if isinstance(base, type):
                mro = getattr(base, '__mro__', None)
                if not mro:
                    raise TypeError('Error when trying to determine deepest metaclass for type: %s' % base)
                metaclass = getattr(base, '__metaclass__', None)
                if metaclass is None:
                    metaclass = type
                for cls in mro[1:]:
                    try:
                        make_mro([cls, metaclass])
                    except (TypeError, AttributeError):
                        # Not all bases are compatible
                        continue
                    metaclass = cls
            elif metaclass is None:
                # at least one explicit metaclass - raise
                raise TypeError('Explicit metaclass %s is incompatible with base %s' % (explicit_mc, base))
            else:
                # Decide whether the param bases is a tuple of types, or a tuple of types and non-types
                # with a metaclass.
                #
                # Rule: the most deeply derived metaclass wins.
                #
                # So unless we can show that metaclass is derived from base's metaclass, we use metaclass
                if not isinstance(base, type):
                    cls = type
                else:
                    cls = type
                for cls in getattr(base, '__mro__', [base]):
                    try:
                        make_mro([cls, metaclass])
                    except (TypeError, AttributeError):
                        # cls is not a base of metaclass
                        continue
                    metaclass = cls
    return metaclass

