def isoparse(self, dt_str):
    delimiter = ""
    if hasattr(dt_str, "read"):
        dt_str = dt_str.read()
        if not isinstance(dt_str, str):
            raise ValueError("Stream is not a string.")

    if len(dt_str) < 5:
        raise ValueError("String is too short.")

    date_part, time_part = self._split_dt(dt_str)

    if delimiter:
        time_part = self._parse_time(time_part)

    date_obj = self._parse_date(date_part)

    if time_part:
        time_obj = self._parse_time(time_part)
    else:
        time_obj = (0, 0, 0, 0)

    hour, minute, second, microsecond = time_obj

    if time_part and time_part[-1] in 'zZ':
        tzinfo = dateutil.tz.tzutc()
    elif 'T' in dt_str and dt_str[-1] in '+-' and len(dt_str) > 1:
        tz_part = dt_str.split('T', 1)[1]
        if 'T' in tz_part:
            tz_part = tz_part.split('T', 1)[1]
        if len(tz_part) == 6 and tz_part[2] == ':':
            tz_str = tz_part
        elif len(tz_part) == 5 and tz_part[1] == ' ':
            tz_str = tz_part
        elif len(tz_part) == 4:
            tz_str = tz_part
        elif len(tz_part) == 5:
            tz_str = tz_part
        else:
            tz_str = tz_part
        try:
            sign = 1 if tz_str[0] == '+' else -1
            tz_part = tz_str[1:]
            if ':' in tz_part:
                parts = tz_part.split(':')
                tz_hours = int(parts[0])
                tz_minutes = int(parts[1]) if len(parts) > 1 else 0
            else:
                tz_hours = int(tz_part[:2])
                tz_minutes = int(tz_part[2:]) if len(tz_part) > 2 else 0
            if tz_hours == 0 and tz_minutes == 0:
                tzinfo = dateutil.tz.tzutc()
            else:
                tzinfo = dateutil.tz.tzoffset(None, sign * (tz_hours * 3600 + tz_minutes * 60))
        except (ValueError, IndexError):
            tzinfo = None
    else:
        tzinfo = None

    return datetime.datetime(date_obj.year, date_obj.month, date_obj.day, hour, minute, second, microsecond, tzinfo)

