        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass

    # Check for legacy payload
    try:
        if isinstance(request.body, bytes):
            body_str = request.body.decode('utf-8', errors='ignore')
        else:
            body_str = request.body

        # Legacy payloads might have specific markers or structures
        if 'diaspora' in body_str.lower():
            return True
    except Exception:
        pass

    return False
