def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    from datetime import datetime
    if dt is None:
        return None
    if isinstance(dt, datetime):
        if dt.tzinfo is not None:
            dt = dt.astimezone(datetime.now().astimezone().tzinfo)
        return dt.strftime("%Y-%m-%dT%H:%M:%S.%f")
    else:
        try:
            # If it's a string, try to parse it and format it
            if isinstance(dt, str):
                # Try to parse the string as a datetime
                dt_obj = datetime.fromisoformat(dt)
                return dt_obj.strftime("%Y-%m-%dT%H:%M:%S.%f")
            # If it's not a string or datetime, try to convert to string
            return str(dt)
        except (ValueError, TypeError) as e:
            # If we can't parse it, just return the string representation
            return str(dt)
