def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        return {}

    result = {}
    # Get children; handle both ET.Element and potential generic iterability
    if hasattr(node, 'getchildren'):
        children = node.getchildren()
    elif hasattr(node, '__iter__'):
        children = list(node)
    else:
        return {}

    for child in children:
        # Determine tag
        if hasattr(child, 'tag'):
            tag = child.tag
        else:
            # Fallback: treat child itself as key-value? Issue says
            # "children of each child ARE entries of the dict".
            # For an Element child, its 'children' are inner elements, not key/val pairs.
            # So, we interpret 'tag' as the key, and we interpret the child's 'text' as its
            # value when it has no children, otherwise collect its direct children
            # recursively in order to accurately escape the prompt.  See below.
            tag = str(child)

        # Cleanup namespace from tag string
        if isinstance(tag, str) and '}' in tag:
            parts = tag.split('}')
            # Common pattern in XML namespaces
            tag = parts[-1]

        if hasattr(child, 'tag') and hasattr(child, '__iter__'):
            len_children = len(list(child))  # Count direct children
        else:
            len_children = 0

        if len_children > 0:
            # Child has children; use their tags, val={'loop_it': dict of
            # grandchildren..}
            grandchildren = []
            for cc in child:
                if hasattr(cc, 'tag') and hasattr(cc, '__iter__'):
                    cc_len = len(list(cc))

                    # Find text
                    if cc_len == 0:
                        # Simple case
                        text = getattr(cc, 'text', None)
                        grandchildren.append({cc.tag: {'loop_it': {'text': text}}})
                    else:
                        grandchildren.append({cc.tag: {'loop_it': xml_children_as_dict(cc)}})

            # If no children? Issue says "append to list if key already exists", which implies that
            # same tag children are appended as a list. But since we are converting each child to a
            # dict already, multiple children with the same tag -> dict keyed by them collapses.
            if tag not in result:
                result[tag] = {'loop_it': grandchildren}
            else:
                if isinstance(result[tag], dict) and 'loop_it' in result[tag] and isinstance(
                        result[tag]['loop_it'], list):
                    # already a list; append? Let's keep a separate list under tag
                    # Append children from xx to existing list
                    existing = result[tag]['loop_it']
                    existing.extend(grandchildren)
                elif isinstance(result[tag], dict) and 'loop_it' in result[tag]:
                    # Existing is a dict
                    new_list = [result[tag]['loop_it']]
                    new_list.extend(grandchildren)
                    result[tag]['loop_it'] = new_list
                else:
                    # Should not happen
                    result[tag] = {'loop_it': grandchildren}
        else:
            # No children; use .text
            text = getattr(child, 'text', None)
            if tag not in result:
                result[tag] = {'loop_it': text}
            else:
                # Append to list if key already exists
                if not isinstance(result[tag], dict):
                    prev = result[tag]
                    result[tag] = {'loop_it': [prev]}
                    result[tag]['loop_it'].append(text)
                else:
                    val = result[tag].get('loop_it')
                    if isinstance(val, list):
                        val.append(text)
                    else:
                        result[tag]['loop_it'] = [val, text]

    # Post-pass: ensure if same-tag children were appended at top level and the
    # top-level dict value ends up wrapped as dict with key tag, then fold in
    # dict-valued children when a same-tag child is attached with
    # loop_it as dict representing child.xml (issue says if child has no
    # children, treat as leaf text; treat child as ... tag ??? issue says
    # "treat the tag as the key, and the text as its value", no children ==
    # leaf)
    # The code above handles that.
    return result
