    except Exception as e:
        logger.warning("get_nodeinfo_well_known_document: failed to fetch nodeinfo document: %s", e)
        return None

    if document:
        try:
            nodeinfo_data = json.loads(document)
        except json.JSONDecodeError:
            logger.warning("get_nodeinfo_well_known_document: failed to parse JSON document")
            return None

        if "links" in nodeinfo_data:
            for link in nodeinfo_data["links"]:
                if link.get("rel") == "http://nodeinfo.diaspora.software/ns/schema/2.0" or \
