                        except Exception as e:
                            logger.warning("get_nodeinfo_well_known_document: failed to fetch nodeinfo document at %s: %s", nodeinfo_document_url, e)
                            return None

                        if nodeinfo_doc:
                            try:
                                return json.loads(nodeinfo_doc)
                            except json.JSONDecodeError:
                                logger.warning("get_nodeinfo_well_known_document: failed to parse nodeinfo document JSON")
                                return None

        # If no links or links didn't yield a result, try the default path
        default_nodeinfo_urls = [
            f"{url.rstrip('/')}/nodeinfo/2.0",
            f"{url.rstrip('/')}/nodeinfo/1.0",
            f"{url.rstrip('/')}/nodeinfo",
            f"{url.rstrip('/')}{document_path}" if document_path else None
        ]

        for test_url in default_nodeinfo_urls:
            if test_url:
                try:
                    nodeinfo_doc, doc_code, doc_exception = fetch_document(url=test_url)
                except Exception as e:
                    logger.warning("get_nodeinfo_well_known_document: failed to fetch nodeinfo document at %s: %s", test_url, e)
                    continue

                if nodeinfo_doc:
                    try:
                        parsed_doc = json.loads(nodeinfo_doc)
                        if isinstance(parsed_doc, dict):
                            return parsed_doc
                    except json.JSONDecodeError:
                        continue

    return None

