    if document_path is None:
        document_path = "/.well-known/nodeinfo"

    query = "%s%s" % (url.rstrip('/'), document_path)
    document, code, exception = fetch_document(query)
    if exception or code != 200:
        return None

    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": "%s%s" % (url.rstrip('/'), "/nodeinfo/2.0.json"),
            },
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": "%s%s" % (url.rstrip('/'), "/nodeinfo/1.0.json"),
            }
        ]
    }

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if url is None:
        raise ValueError("url must be provided")

    if not isinstance(url, str) or not url.strip():
        raise ValueError("url must be a non-empty string")

    default_path = "/.well-known/nodeinfo"
    if document_path is not None:
        if not isinstance(document_path, str) or not document_path.strip():
            raise ValueError("document_path must be a non-empty string if provided")
        path = document_path.strip()
    else:
        path = default_path

    if not path.startswith('/'):
        path = '/' + path

    full_url = url.rstrip('/') + path

    try:
        req = urllib.request.Request(full_url)
        resp = urllib.request.urlopen(req)
        data = resp.read()
    except Exception as e:
        logger.warning("Error fetching nodeinfo document from %s: %s", full_url, e)
        return {"error": "Request failed: " + str(e)}

    try:
        result = json.loads(data.decode('utf-8'))
    except Exception as e:
        logger.warning("Error parsing nodeinfo JSON from %s: %s", full_url, e)
        return {"error": "JSON parse error: " + str(e)}

    return result

