def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        if not public_key:
            raise ValueError("public_key cannot be None or empty")
        if not doc:
            raise ValueError("doc cannot be None or empty")
        if not signature:
            raise ValueError("signature cannot be None or empty")

        # Check the type of doc
        if isinstance(doc, bytes):
            document = doc
        elif isinstance(doc, str):
            try:
                document = doc.encode('utf-8')
            except Exception as e:
                raise ValueError("Invalid document") from e
        else:
            raise TypeError("doc must be bytes, str or file-like")

        try:
            return public_key.verify(bytes(signature), document, 'sha256')
        except Exception as e:
            raise ValueError("Verification failed") from e
    except Exception as e:
        raise e
