def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        import json

        data = json.loads(document)
        if isinstance(data, dict) and "links" in data:
            links = data["links"]
            result = {}
            for link in links:
                rel = link.get("rel")
                if rel == "diaspora":
                    result["diaspora_url"] = link.get("url")
                elif rel == "lrdd":
                    result["lrdd_url"] = link.get("url")
                elif rel == "http://webfinger.net/rel/profile-page":
                    result["profile_url"] = link.get("url")
                elif rel == "hcard":
                    result["hcard_url"] = link.get("url")
            return result
    except json.JSONDecodeError:
        pass

    # Try parsing as XRD
    try:
        from lxml import etree

        parser = etree.XMLParser(recover=True, resolve_entities=False)
        root = etree.fromstring(document.encode("utf-8"), parser)
        root.tag = etree.QName(root.tag).localname

        result = {}
        for link in root.iter("link"):
            rel = link.get("rel")
            if rel == "lrdd":
                template = link.get("template")
                if template:
                    result["lrdd_url"] = template
            elif rel in ("hcard", "http://webfinger.net/rel/hcard"):
                href = link.get("href")
                if href:
                    result["hcard_url"] = href
        return result
    except Exception:
        pass

    return {}
