def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from lxml import etree
    from urllib.parse import urlparse

    if not isinstance(document, str):
        return {"subject": None, "aliases": [], "links": []}

    document_stripped = document.strip()
    if not document_stripped:
        return {"subject": None, "aliases": [], "links": []}

    # Try JSON format first (modern webfinger)
    json_result = None
    try:
        json_data = json.loads(document_stripped)
        if isinstance(json_data, dict):
            subject = json_data.get("subject")
            aliases = json_data.get("aliases", [])
            links = json_data.get("links", [])

            # Normalize links to have consistent keys
            normalized_links = []
            for link in links:
                if isinstance(link, dict):
                    normalized_link = {
                        "rel": link.get("rel"),
                        "href": link.get("href"),
                        "type": link.get("type"),
                        "template": link.get("template")
                    }
                    # Only include keys that are present
                    normalized_link = {k: v for k, v in normalized_link.items() if v is not None}
                    normalized_links.append(normalized_link)

            json_result = {
                "subject": subject,
                "aliases": aliases if isinstance(aliases, list) else [],
                "links": normalized_links
            }
    except (json.JSONDecodeError, ValueError):
        pass

    # If JSON parsing succeeded, return the result
    if json_result is not None:
        return json_result

    # Fall back to XRD format (old webfinger)
    try:
        # Remove XML declaration if present
        xrd_content = document_stripped
        if xrd_content.startswith("<?xml"):
            end_of_decl = xrd_content.find("?>")
            if end_of_decl != -1:
                xrd_content = xrd_content[end_of_decl + 2:].strip()

        root = etree.fromstring(xrd_content.encode("utf-8"))

        # Namespaces used in XRD/webfinger
        ns_map = {
            "xn": "http://wildcardproxy.org/spec/xrd/1.0",
            "xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0",
            "atom": "http://www.w3.org/2005/Atom",
            "lrdd": "http://LRDD.lannick.piwowar.sk/",
            "diaspora": "http://diaspora.org/ns/"
        }

        subject = None
        aliases = []
        links = []

        # Find subject
        subject_elem = root.find("xn:Subject", ns_map)
        if subject_elem is not None:
            subject = subject_elem.text

        # Find aliases
        for alias_elem in root.findall("xn:Aliases/xn:Alias", ns_map):
            if alias_elem.text:
                aliases.append(alias_elem.text)

        # Find links
        for link_elem in root.findall("xn:Links/xn:Link", ns_map):
            rel = link_elem.get("rel")
            href = link_elem.get("href")
            type_attr = link_elem.get("type")
            template = link_elem.get("template")

            normalized_link = {}
            if rel:
                normalized_link["rel"] = rel
            if href:
                normalized_link["href"] = href
            if type_attr:
                normalized_link["type"] = type_attr
            if template:
                normalized_link["template"] = template

            if normalized_link:
                links.append(normalized_link)

        result = {
            "subject": subject,
            "aliases": aliases,
            "links": links
        }
        return result

    except Exception:
        # If XRD parsing fails, return a default structure
        return {"subject": None, "aliases": [], "links": []}

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        # First, try to parse as JSON
        data = json.loads(document)
    except json.JSONDecodeError:
        # If JSON parsing fails, try to parse as XRD
        try:
            xrd_tree = fromstring(document)
            return _parse_xrd(xrd_tree)
        except (ParseError, TypeError, ValueError):
            return {"subject": None}

    # Ensure the data is a dictionary
    if not isinstance(data, dict):
        return {"subject": None}

    # Check for the subject field
    if "subject" not in data:
        return {"subject": None}

    # Look for the aliases and links fields
    aliases = data.get("aliases", [])
    links = data.get("links", [])

    hcard_url = None
    for link in links:
        if isinstance(link, dict) and link.get("rel") == "http://webfinger.net/rel/profile-page":
            hcard_url = link.get("href")
            break

    return {
        "subject": data["subject"],
        "aliases": aliases,
        "hcard_url": hcard_url
    }

