            response = requests.head(url, timeout=timeout, *args, **kwargs)
        elif method == "patch":
            response = requests.patch(url, data=data, timeout=timeout, *args, **kwargs)
        else:
            return None, ValueError("Unsupported method: %s" % method)

        return response.status_code, None
    except Exception as ex:
        return None, ex

