                    included_dict = yaml.safe_load(include_f)
                # Merge the included dict into the current group dict
                for include_key, include_value in included_dict.items():
                    if include_key not in group_dict:
                        group_dict[include_key] = include_value
            except Exception as e:
                raise ValueError("Failed to include file: {}".format(include_file)) + e
            del group_dict['include']
