def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    included_groups = parser_dict.pop('%', None)
    if included_groups is None:
        return
    if isinstance(included_groups, str):
        included_groups = [included_groups]
    if not isinstance(included_groups, (list, tuple)):
        raise ValueError('include directive should be a string or a list of strings')
    for group_name in included_groups:
        if not isinstance(group_name, str):
            raise ValueError('include directive list should be strings')
        reflected = self._global_state.find_group(group_name)
        if reflected is None:
            raise KeyError('group %r not found' % group_name)
        for key, value in reflected.items():
            if key not in parser_dict:
                parser_dict[key] = value
            else:
                # if the key already exists, check if it is a dict
                if isinstance(parser_dict[key], dict) and isinstance(value, dict):
                    # merge the dicts
                    nested = parser_dict[key].copy()
                    for subkey, subvalue in value.items():
                        nested[subkey] = subvalue
                    parser_dict[key] = nested
                else:
                    parser_dict[key] = value
