def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    includes = parser_dict.get('include_none', None)
    parser_dict.pop('include_none', None) if 'include_none' in parser_dict else None
    include = parser_dict.get('include', None)
    parser_dict.pop('include', None) if 'include' in parser_dict else None
    if (include or includes) and 'unpack' in parser_dict:
        raise ValueError('The "unpack" directive can only be used when include(None)')
    if include or includes:
        if 'unpack' in parser_dict:
            raise ValueError('The "unpack" directive can only be used with a dict')
        unpack = parser_dict.pop('unpack', False)
        if unpack:
            include = dict()
            if include:
                include.update(self._include(parser_dict, include))
            if includes:
                include.update(self._include(parser_dict, includes, autoload=None))
            parser_dict.update(include)
        else:
            if 'register' in parser_dict.values():
                raise ValueError('The "register" directive can only be used with a dict')
            include = self._include(parser_dict, include)
            if includes:
                include = self._include(None, None, autoload=None)

