def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    options = []
    for parser in self._parsers:
        if parser.prog and parser.prog.startswith(command_name):
            for option in parser._option_strings.items():
                options.append(option)
                for sub_option in option[1]._option_strings.items():
                    options.append(sub_option)
    return options

def get_parser_option_specs(self, command_name):
    parser = self.get_parser(command_name)
    specs = []
    for group in parser.option_groups:
        for opt in group.option_list:
            specs.append(opt)
    for opt in parser.option_list:
        if all(opt not in g.option_list for g in parser.option_groups):
            specs.append(opt)
    return specs

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    self._update_option_formats()

    all_option_types = None
    command_options = self._command_option_map.get(command_name, NONE)

    if command_options:
        all_option_types = [command_options]
    specified = self.get_specified(command_name, argument_name)
    for option_type in all_option_types:
        option_spec = option_type.spec
        try:
            return option_spec[argument_name]
        except KeyError:
            break
    return self._default_argument_spec

