    if command_name in self.option_spec:
        spec = self.option_spec[command_name]

        # Check if argument_name is a key in the command-specific specs
        if argument_name in spec:
            return spec[argument_name]

        # If it's a list, check the list
        if isinstance(spec, list):
            for entry in spec:
                if isinstance(entry, dict) and argument_name in entry:
                    return entry[argument_name]
        elif isinstance(spec, dict):
            # Already checked above, but just in case
            pass

    # Next, look in the global spec store
    if global_option_spec and argument_name in global_option_spec:
        return global_option_spec[argument_name]

    return spec
