def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    if not isinstance(options_spec, list):
        return []

    matched_args = []
    for spec in options_spec:
        if not isinstance(spec, dict):
            continue
        required_when = spec.get('required_when')
        if required_when is not None:
            condition_met = False
            if isinstance(args, dict):
                # Check if the condition key exists in args and its value is truthy
                if required_when in args and args[required_when]:
                    condition_met = True
            else:
                # Try to check if args can be iterated or has attribute
                try:
                    if hasattr(args, required_when) and getattr(args, required_when):
                        condition_met = True
                    elif isinstance(args, (list, tuple)):
                        # Fallback: if args is a list, maybe it contains command name?
                        # Actually, typical usage: required_when is a boolean flag in args
                        pass
                except Exception:
                    condition_met = False

            if condition_met:
                arg_name = spec.get('name')
                if arg_name is not None:
                    matched_args.append(arg_name)

    return matched_args

def _get_conditionally_required_args(self, command_name, options_spec, args):
    required_args = []
    for item in options_spec:
        arg_name = item.get('name', None)
        if arg_name is None:
            continue
        required_when = item.get('required_when', None)
        if required_when is None:
            continue
        if required_when.startswith(command_name):
            required_args.append(arg_name)
    return required_args

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
            condition
    """
    args_list = []
    for spec in (options_spec or []):
        try:
            spec_dict = spec
            arg_name = spec_dict.get('name') or spec_dict.get('arg')
            if not arg_name:
                # try to derive from options list items (e.g. ['--name', ...])
                if isinstance(spec_dict.get('options'), (list, tuple)) and spec_dict['options']:
                    arg_name = str(spec_dict['options'][0]).lstrip('-').replace('-', '_')
                else:
                    continue

            required_when = spec_dict.get('required_when')
            if not required_when:
                continue

            condition_matched = True
            if isinstance(required_when, (list, tuple)):
                for cond in required_when:
                    if isinstance(cond, (list, tuple)) and len(cond) >= 2:
                        flag, expected = cond[0], cond[1]
                        # normalize flag name to attribute
                        flag_attr = str(flag).lstrip('-').replace('-', '_')
                        current_val = getattr(args, flag_attr, None)
                        if current_val != expected:
                            condition_matched = False
                            break
                    elif callable(cond):
                        try:
                            if not cond(command_name, args):
                                condition_matched = False
                                break
                        except Exception:
                            condition_matched = False
                            break
                    else:
                        # unsupported condition type -> treat as not matched
                        condition_matched = False
                        break
            elif callable(required_when):
                try:
                    if not required_when(command_name, args):
                        condition_matched = False
                except Exception:
                    condition_matched = False

            if condition_matched:
                args_list.append(str(arg_name))
        except Exception:
            # skip malformed spec entries
            continue
    return args_list

