def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if not hasattr(self, 'min') or not hasattr(self, 'max'):
        return
    if self.min is None or self.max is None:
        return
    min_val = self.min
    max_val = self.max
    for arg in args:
        if not isinstance(arg, (int, float)):
            continue
        if arg < min_val or arg > max_val:
            raise ValueError(
                "Argument {} is out of the valid range [{} - {}].".format(arg, min_val, max_val)
            )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if args is None:
        raise ValueError("args cannot be None")

    # Convert args to a list if it's not already iterable
    try:
        arg_list = list(args)
    except TypeError:
        raise TypeError("args must be an iterable of arguments")

    for i, arg in enumerate(arg_list):
        if not hasattr(arg, 'min') or not hasattr(arg, 'max'):
            continue

        min_val = arg.min
        max_val = arg.max

        if min_val is None or max_val is None:
            raise ValueError(
                f"Argument at index {i} must define both min and max values"
            )

        if min_val > max_val:
            raise ValueError(
                f"Minimum value ({min_val}) cannot be greater than "
                f"maximum value ({max_val}) for argument at index {i}"
            )

        # If the argument has a value attribute, validate it
        if hasattr(arg, 'value'):
            value = arg.value
            if value < min_val:
                raise ValueError(
                    f"Value ({value}) is less than minimum ({min_val}) "
                    f"for argument at index {i}"
                )
            if value > max_val:
                raise ValueError(
                    f"Value ({value}) is greater than maximum ({max_val}) "
                    f"for argument at index {i}"
                )

    return args

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary")

    for arg_name, arg_value in args.items():
        if arg_name == 'min' or arg_name == 'max':
            if not isinstance(arg_value, (int, float)):
                raise TypeError("Value for '{}' must be a number".format(arg_name))
            if arg_name == 'min' and 'max' in args and isinstance(args['max'], (int, float)):
                if arg_value > args['max']:
                    raise ValueError("Minimum value cannot be greater than maximum value")
            elif arg_name == 'max' and 'min' in args and isinstance(args['min'], (int, float)):
                if arg_value < args['min']:
                    raise ValueError("Maximum value cannot be less than minimum value")

