def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    if type_name not in self.complex_types:
        raise ValueError(f"Invalid complex type: {type_name}")

    # Get the complex type constructor
    type_constructor = self.complex_types[type_name]

    # Extract parameters from spec
    params = {}
    if spec_option is not None:
        if hasattr(spec_option, 'kwargs'):
            params = spec_option.kwargs or {}
        elif isinstance(spec_option, dict):
            params = spec_option

    # Build the complex type instance
    try:
        complex_instance = type_constructor(subcommand, option_name, **params)
    except TypeError as e:
        raise ValueError(
            f"Failed to create complex argument type '{type_name}' for option "
            f"'{option_name}' in subcommand '{subcommand}': {e}"
        )

    return complex_instance

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    if not args:
        return {}, {}

    control_args = {}
    nested_args = {}

    for arg in args:
        # Extract key=value pairs, handling potential nested key=value
        if '=' not in arg:
            continue

        key, value = arg.split('=', 1)

        # Check if it's a control argument based on naming convention or known prefixes
        # For demonstration, assume control args start with specific prefixes or are in a known set
        # Let's assume any key starting with 'run_' is a control argument
        if key.startswith('run_'):
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

