def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg.startswith('-'):
            # This is a control argument (e.g., -c, --control)
            control_arg_name = arg.lstrip('-').replace('--', '')
            # Extract key and value if present
            parts = arg.split('=', 1)
            if len(parts) == 2:
                key, value = parts[0].lstrip('-'), parts[1]
                control_args[key] = value
            else:
                control_args[key] = None
        else:
            # This could be a nested argument or a custom argument
            parts = arg.split('=', 1)
            if len(parts) == 2:
                key, value = parts
                if key.startswith('custom:'):
                    custom_args[key.replace('custom:', '')] = value
                else:
                    nested_args[key] = value
            else:
                # If no '=' is present, treat it as a custom argument with a boolean True value
                custom_args[parts[0]] = 'true'

    return control_args, nested_args
