def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    if not args:
        return control_args, nested_args

    try:
        for arg in args:
            if isinstance(arg, str):
                parts = arg.split('=', 1)
                if len(parts) == 2:
                    key, value = parts
                    key = key.strip()
                    value = value.strip()

                    # Determine if this is a control argument or a nested/custom argument
                    # Control arguments typically start with specific prefixes or are in a known list
                    # Here we assume any argument that matches certain keywords or prefixes is control
                    control_keywords = {'debug', 'verbose', 'force', 'timeout', 'log_level'}

                    if key in control_keywords or key.lower().startswith('control_'):
                        control_args[key] = value
                    elif key.startswith('v_') or key.startswith('set_') or key.startswith('custom_'):
                        # These are typically passed directly to scalars/variables
                        nested_args[key] = value
                    else:
                        # Default to nested if not explicitly control
                        nested_args[key] = value
                else:
                    # If no equals sign, treat as a boolean flag or control arg if it matches
                    key = arg.strip()
                    if key in control_keywords:
                        control_args[key] = True
                    else:
                        nested_args[key] = True

            elif isinstance(arg, dict):
                # Handle dictionary arguments directly
                for k, v in arg.items():
                    if k in ('debug', 'verbose', 'force', 'timeout', 'log_level'):
                        control_args[k] = v
                    else:
                        nested_args[k] = v
            else:
                # Ignore unsupported types
                continue

    except Exception:
        # If there's an unexpected error, return the processed parts so far
        pass

    return control_args, nested_args

