def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Build the base command
    cmd = ["ansible-playbook"]

    # If ansible_args is a dict, convert keys to '--key' and values to their string representation
    if ansible_args:
        for key, val in ansible_args.items():
            cmd.append("--{}".format(key))
            if val is None:
                cmd.append("")
            elif isinstance(val, bool):
                cmd.append("true" if val else "false")
            else:
                cmd.append(str(val))

    # Add --extra-vars if provided
    if extra_vars:
        evars = {}
        for k, v in extra_vars.items():
            if isinstance(v, (list, dict)):
                # Convert complex types to JSON string
                evars[k] = json.dumps(v)
            else:
                evars[k] = str(v)
        # Format as key=value pairs and join with a single argument? 
        # Ansible syntax: --extra-vars "key1=val1 key2=val2"
        # Or dict. JSON is safer.
        cmd.extend(["--extra-vars", json.dumps(extra_vars)])

    # Add -v flags for verbosity
    if verbose:
        if isinstance(verbose, int) and verbose >= 0:
            if verbose == 1:
                cmd.append("-v")
            elif verbose >= 2:
                cmd.append("-v" * verbose)
        else:
            # If passed as a string or other type, just log?
            # Stick to int support for safety

    # Add the playbook path
    cmd.append(playbook_path)

    # Log the command
    ir_workspace.debug("ansible-playbook command: {}".format(" ".join(cmd)))

    # Run the command
    # ir_plugin.utils is assumed to provide subprocess run capabilities
    # Usually in Infrared: ir_plugin.utils.subprocess.run
    try:
        result = ir_plugin.utils.subprocess.run(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            universal_newlines=True,
        )
        if result.returncode != 0:
            ir_workspace.error("ansible-playbook failed with exit code {}: {}".format(result.returncode, result.stderr))
            raise Exception("ansible-playbook failed: {}".format(result.stderr))

        if result.stdout:
            ir_workspace.debug("ansible-playbook stdout: {}".format(result.stdout))
        return result.stdout
    except Exception as e:
        ir_workspace.error("Error running ansible-playbook: {}".format(str(e)))
        raise

